// ============================================================================
// DOMOBY - Formulario "Dados do pedido" -> Tiny (contato)
// Node "Normalizar e validar". Mode: Run Once for All Items.
//
// Entrada : linhas novas da aba "Respostas ao formulario 1"
// Saida   : 1 item por resposta, com o payload do Tiny ja montado e o veredito
//           do documento.
//
// REGRA CENTRAL (decidida em 13/08, confirmada em 01/09):
//   documento que NAO passa no digito verificador nao vai para o Tiny.
//   O cliente e cadastrado sem documento, o valor digitado fica em obs e a
//   linha vai para a aba PENDENCIAS. Melhor cliente sem CPF que CPF errado.
//   E isso que resolve a queixa "o Tiny nao deixa cadastrar com CPF errado":
//   nada com digito invalido chega la.
//
// CABECALHOS DA PLANILHA - tres terminam com espaco: 'Rua ', 'CPF ',
// 'End. Numero '. Nao "arrumar" esses nomes, sao literais da aba.
// ============================================================================

// --- helpers -----------------------------------------------------------------
const txt = (v) => (v === null || v === undefined ? '' : String(v));
const limpa = (v) => txt(v).replace(/\s+/g, ' ').trim();
const digitos = (v) => txt(v).replace(/\D/g, '');

// primeiro valor nao vazio (usado onde a planilha tem cabecalho duplicado)
const oPrimeiro = (...vs) => {
  for (const v of vs) if (limpa(v) !== '') return limpa(v);
  return '';
};

const UFS = ['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG',
             'PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];

// --- validacao real de CPF (digito verificador) ------------------------------
function cpfValido(d) {
  if (!/^\d{11}$/.test(d)) return false;
  if (/^(\d)\1{10}$/.test(d)) return false; // 000.000.000-00, 111... sao recusados
  let s = 0;
  for (let i = 0; i < 9; i++) s += Number(d[i]) * (10 - i);
  let r = (s * 10) % 11;
  if (r === 10) r = 0;
  if (r !== Number(d[9])) return false;
  s = 0;
  for (let i = 0; i < 10; i++) s += Number(d[i]) * (11 - i);
  r = (s * 10) % 11;
  if (r === 10) r = 0;
  return r === Number(d[10]);
}

// --- validacao real de CNPJ (digito verificador) ------------------------------
function cnpjValido(d) {
  if (!/^\d{14}$/.test(d)) return false;
  if (/^(\d)\1{13}$/.test(d)) return false;
  const calc = (base) => {
    let peso = base.length === 12 ? 5 : 6;
    let s = 0;
    for (let i = 0; i < base.length; i++) {
      s += Number(base[i]) * peso;
      peso = peso === 2 ? 9 : peso - 1;
    }
    const r = s % 11;
    return r < 2 ? 0 : 11 - r;
  };
  if (calc(d.slice(0, 12)) !== Number(d[12])) return false;
  return calc(d.slice(0, 13)) === Number(d[13]);
}

const mascaraCPF = (d) =>
  `${d.slice(0, 3)}.${d.slice(3, 6)}.${d.slice(6, 9)}-${d.slice(9)}`;
const mascaraCNPJ = (d) =>
  `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5, 8)}/${d.slice(8, 12)}-${d.slice(12)}`;

// O Google Sheets come o zero a esquerda quando trata a celula como NUMERO -
// "08735920777" vira 8735920777. Acontece em edicao manual da planilha e em
// qualquer importacao que nao force texto.
// Recuperamos devolvendo o zero, mas SO aceitamos se o resultado passar no
// digito verificador (chance de acertar por acaso: 1 em 100).
function reporZeroAEsquerda(d) {
  if (d.length === 10) { const t = '0' + d; if (cpfValido(t)) return t; }
  if (d.length === 9)  { const t = '00' + d; if (cpfValido(t)) return t; }
  if (d.length === 13) { const t = '0' + d; if (cnpjValido(t)) return t; }
  return d;
}

// Cliente digita letra no lugar de numero (O->0, I/l->1, S->5, B->8).
// So aceitamos a correcao se o resultado passar no digito verificador:
// a chance de um numero errado passar por acaso e de 1 em 100.
function corrigirConfusaoDeTeclado(bruto) {
  const t = txt(bruto).replace(/[Oo]/g, '0').replace(/[Il|]/g, '1')
                      .replace(/[Ss]/g, '5').replace(/[Bb]/g, '8');
  return digitos(t);
}

// --- data/hora ---------------------------------------------------------------
// O Google Sheets pode entregar o carimbo de duas formas, conforme a opcao
// "Value Render" do node: como texto ("02/09/2026 11:42:17") ou como NUMERO
// de serie do Sheets (dias desde 30/12/1899). Aqui os dois viram texto.
function dataHora(v) {
  if (v === null || v === undefined || v === '') return '';
  const n = typeof v === 'number' ? v : (/^\d+([.,]\d+)?$/.test(String(v).trim())
    ? parseFloat(String(v).replace(',', '.')) : NaN);
  if (!Number.isFinite(n) || n < 20000 || n > 80000) return limpa(v); // ja e texto
  const ms = Math.round((n - 25569) * 86400000); // 25569 = 01/01/1970 no Sheets
  const d = new Date(ms);
  if (isNaN(d.getTime())) return limpa(v);
  const p = (x) => String(x).padStart(2, '0');
  return `${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}/${d.getUTCFullYear()} ` +
         `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}:${p(d.getUTCSeconds())}`;
}

// --- CEP ---------------------------------------------------------------------
function formataCEP(v) {
  const d = digitos(v);
  if (d.length !== 8) return '';
  return `${d.slice(0, 5)}-${d.slice(5)}`;
}

// --- telefone ----------------------------------------------------------------
// A planilha traz "84988929748", "84 99173-7018 ", "(067)981235476", "996466798".
function formataFone(v) {
  let d = digitos(v);
  if (d.startsWith('55') && (d.length === 12 || d.length === 13)) d = d.slice(2); // +55
  if (d.startsWith('0') && (d.length === 11 || d.length === 12)) d = d.slice(1);  // "(067)"
  if (d.length === 11) return `(${d.slice(0, 2)}) ${d.slice(2, 7)}-${d.slice(7)}`;
  if (d.length === 10) return `(${d.slice(0, 2)}) ${d.slice(2, 6)}-${d.slice(6)}`;
  return d; // 8/9 digitos sem DDD, ou lixo: manda cru, o Tiny aceita texto
}

// --- cidade / UF -------------------------------------------------------------
// A planilha traz "Natal/RN", "Natal RN ", "Natal - RN", "PARNAMIRIM".
// Devolve { cidade, ufDaCidade } com a UF arrancada do fim quando existir.
function separaCidadeUF(v) {
  const c = limpa(v);
  if (!c) return { cidade: '', ufDaCidade: '' };
  // O separador e OBRIGATORIO. Sem ele, "Natal" viraria cidade "Nat" + UF "AL".
  const m = c.match(/^(.+?)\s*[\/,\-]\s*([A-Za-z]{2})\.?$/) // Natal/RN, Natal - RN, Natal, RN
         || c.match(/^(.+?)\s+([A-Za-z]{2})\.?$/);           // Natal RN
  if (m) {
    const uf = m[2].toUpperCase();
    const resto = limpa(m[1]).replace(/[\/\-,]+$/, '').trim();
    if (UFS.includes(uf) && resto.length >= 3) return { cidade: resto, ufDaCidade: uf };
  }
  return { cidade: c, ufDaCidade: '' };
}

// Title Case. `sempre=false` so age quando o cliente escreveu TUDO EM MAIUSCULA
// (respeita "Elisiane Aires da Silva"); `sempre=true` normaliza sempre (cidade).
const MINUSCULAS = new Set(['de','da','do','das','dos','e','du','del','di','na','no']);
function arrumaCaixa(s, sempre = false) {
  const v = limpa(s);
  if (!v) return '';
  if (!sempre && (v !== v.toUpperCase() || v.length < 4)) return v;
  return v
    .toLowerCase()
    .split(' ')
    .map((p, i) => (i > 0 && MINUSCULAS.has(p) ? p
      : p.replace(/^([a-zà-ÿ])/, (c) => c.toUpperCase())))
    .join(' ');
}

// --- numero do endereco ------------------------------------------------------
// Respostas antigas nao tinham "End. Numero": o numero vinha colado na rua
// ("Rua Esplendor 55"). So extraimos quando a coluna propria esta vazia.
function separaRuaNumero(rua, numeroInformado) {
  const num = limpa(numeroInformado);
  let r = limpa(rua).replace(/[,\s]+$/, '');
  if (num) return { endereco: r, numero: num.slice(0, 10) };
  const m = r.match(/^(.*?)[,\s]+(\d{1,6}[A-Za-z]?)$/);
  if (m && limpa(m[1]).length >= 3) {
    return { endereco: limpa(m[1]).replace(/[,\s]+$/, ''), numero: m[2] };
  }
  return { endereco: r, numero: '' };
}


// ============================================================================
// >>> TRAVA DE HISTORICO — AJUSTE ANTES DE PUBLICAR <<<
// So processa respostas a partir desta data/hora.
//
// POR QUE ISSO EXISTE (incidente de 03/09):
// Um "Execute step" no node do Tiny mostrou 806 items na entrada — o Google
// Sheets Trigger, quando roda a mao, entrega a ABA INTEIRA, nao so as linhas
// novas. Sem esta trava, um clique errado cadastraria 4 anos de respostas no
// Tiny de uma vez. A trava torna isso impossivel por construcao, seja em teste,
// seja se o trigger reprocessar tudo na primeira ativacao.
//
// Formato: 'AAAA-MM-DDTHH:MM'. Ponha o momento em que for publicar.
// ============================================================================
const PROCESSAR_A_PARTIR_DE = '2026-09-03T00:00';

// Converte 'dd/mm/aaaa hh:mm:ss' para 'aaaa-mm-ddThh:mm' (comparavel como texto)
function chaveDoCarimbo(c) {
  const m = String(c).match(/^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})/);
  return m ? `${m[3]}-${m[2]}-${m[1]}T${m[4]}:${m[5]}` : null;
}

// --- corpo -------------------------------------------------------------------
function normalizarLinha(r) {
  // Cabecalhos LITERAIS da aba (tres deles terminam com espaco - nao remover!)
  const carimbo   = dataHora(r['Carimbo de data/hora']);
  const nome      = arrumaCaixa(r['Nome completo']);
  const foneBruto = r['Número de telefone'];
  const ruaBruta  = r['Rua '] ?? r['Rua'];
  const bairro    = arrumaCaixa(r['Bairro']);
  const cidadeCol = r['Cidade'];
  const cepBruto  = r['CEP'];
  const docBruto  = limpa(r['CPF '] ?? r['CPF']);
  const email     = limpa(r['E-mail']).toLowerCase();
  const origem    = limpa(r['Como nos conheceu?']);
  const obsCli    = limpa(r['Alguma observação sobre seu pedido?']);
  const numBruto  = r['End. Número '] ?? r['End. Número'];
  const estadoCol = limpa(r['Estado']).toUpperCase();
  // cabecalho "Complemento" aparece duas vezes na planilha (colunas O e Q).
  // A coluna viva e a O; a Q ficou morta. Lemos as duas grafias possiveis.
  const complemento = oPrimeiro(
    r['Complemento'], r['Complemento_1'], r['Complemento 1'], r['Complemento (2)']
  );

  // ---- CEP x CPF: o cliente confunde os dois campos ----
  // Achado nos 805 registros reais: 8 respostas trazem um CPF VALIDO no campo CEP.
  // Em 7 delas o CPF tambem esta no campo certo (so o CEP se perdeu);
  // em 1 os dois campos estao trocados de lugar.
  let cepUsar = cepBruto;
  let docUsar = docBruto;
  let camposTrocados = false;
  let cpfNoCampoCep = false;
  const dCep = digitos(cepBruto);
  const dDoc = digitos(docBruto);
  if (dCep.length === 11 && cpfValido(dCep)) {
    if (dDoc.length === 8 && !(dDoc.length === 11 && cpfValido(dDoc))) {
      cepUsar = dDoc;  // o CEP estava no campo do CPF
      docUsar = dCep;  // e o CPF no campo do CEP
      camposTrocados = true;
    } else {
      cepUsar = '';    // o campo CEP na verdade tem o CPF: nao ha CEP nesta resposta
      cpfNoCampoCep = true;
    }
  }

  // ---- documento ----
  let tipo_pessoa = 'F';
  let cpf_cnpj = '';
  let docStatus = 'vazio';
  let docCorrigido = false;
  let zeroReposto = false;

  if (docUsar !== '') {
    let d = digitos(docUsar);
    const antesDoZero = d;
    d = reporZeroAEsquerda(d);
    zeroReposto = d !== antesDoZero;
    if (d.length !== 11 && d.length !== 14) {
      const tentativa = corrigirConfusaoDeTeclado(docUsar);
      if ((tentativa.length === 11 && cpfValido(tentativa)) ||
          (tentativa.length === 14 && cnpjValido(tentativa))) {
        d = tentativa;
        docCorrigido = true;
      }
    } else if ((d.length === 11 && !cpfValido(d)) || (d.length === 14 && !cnpjValido(d))) {
      const tentativa = corrigirConfusaoDeTeclado(docUsar);
      if ((tentativa.length === 11 && cpfValido(tentativa)) ||
          (tentativa.length === 14 && cnpjValido(tentativa))) {
        d = tentativa;
        docCorrigido = true;
      }
    }

    if (d.length === 11 && cpfValido(d)) {
      tipo_pessoa = 'F'; cpf_cnpj = mascaraCPF(d); docStatus = 'cpf';
    } else if (d.length === 14 && cnpjValido(d)) {
      tipo_pessoa = 'J'; cpf_cnpj = mascaraCNPJ(d); docStatus = 'cnpj';
    } else {
      docStatus = 'invalido';
    }
  }

  // ---- endereco ----
  const { endereco, numero } = separaRuaNumero(ruaBruta, numBruto);
  const sep = separaCidadeUF(cidadeCol);
  const cidade = arrumaCaixa(sep.cidade, true); // o Tiny casa a cidade pela tabela dele
  const ufDaCidade = sep.ufDaCidade;
  let uf = UFS.includes(estadoCol) ? estadoCol : '';
  if (!uf && ufDaCidade) uf = ufDaCidade;

  // ---- observacoes (limite de 200 caracteres no Tiny) ----
  const partes = [];
  if (docStatus === 'invalido') {
    partes.push(`⚠️ CPF/CNPJ informado nao passou na validacao: ${docBruto}`);
  }
  if (obsCli) partes.push(obsCli);
  if (origem) partes.push(`Origem: ${origem}`);
  const obs = partes.join(' | ').slice(0, 200);

  // ---- payload do Tiny ----
  const contato = {
    sequencia: 1,
    nome: nome.slice(0, 50),
    tipo_pessoa,
    situacao: 'A',
    tipos_contato: [{ tipo: 'Cliente' }],
  };
  const opcional = {
    cpf_cnpj,
    endereco: endereco.slice(0, 50),
    numero: numero.slice(0, 10),
    complemento: complemento.slice(0, 50),
    bairro: bairro.slice(0, 30),
    cep: formataCEP(cepUsar),
    cidade: cidade.slice(0, 30),
    uf,
    fone: formataFone(foneBruto).slice(0, 40),
    email: email.slice(0, 50),
    email_nfe: email.slice(0, 50),
    obs,
  };
  // campo vazio NAO e enviado (evita apagar dado bom no contato.alterar)
  for (const [k, v] of Object.entries(opcional)) if (v !== '') contato[k] = v;

  // ---- alertas para a aba PENDENCIAS ----
  // "bloqueio" = nada vai para o Tiny. "atencao" = cadastra e avisa.
  const alertas = [];
  let bloqueia = false;
  if (!nome) { alertas.push('Nome em branco'); bloqueia = true; }
  if (docStatus === 'invalido') alertas.push(`CPF/CNPJ invalido ("${docBruto}") - cadastrado SEM documento`);
  if (docStatus === 'vazio') alertas.push('Sem CPF/CNPJ - nao da para checar duplicidade nem emitir nota');
  if (docCorrigido) alertas.push('Documento tinha letra no lugar de numero - corrigido e validado');
  if (zeroReposto) alertas.push('Documento estava sem o zero a esquerda (a planilha comeu) - reposto e validado');
  if (camposTrocados) alertas.push('Cliente trocou os campos CEP e CPF de lugar - desinvertido automaticamente');
  if (cpfNoCampoCep) alertas.push(`Cliente digitou o CPF no campo CEP ("${limpa(cepBruto)}") - resposta ficou SEM CEP`);
  if (!contato.cep && !cpfNoCampoCep) alertas.push(`CEP nao reconhecido ("${limpa(cepBruto)}")`);
  if (!contato.uf) alertas.push('UF em branco');
  if (contato.fone && !/^\(\d{2}\)/.test(contato.fone)) alertas.push(`Telefone sem DDD ("${limpa(foneBruto)}")`);
  if (!contato.email) alertas.push('E-mail em branco');

  return {
    carimbo,
    // 8 digitos limpos para a consulta no ViaCEP; vazio quando nao ha CEP util
    cepDigitos: digitos(cepUsar).length === 8 ? digitos(cepUsar) : '',
    docBruto,
    docDigitos: cpf_cnpj ? digitos(cpf_cnpj) : '',
    docStatus,
    docCorrigido,
    zeroReposto,
    camposTrocados,
    tipo_pessoa,
    contato,
    bloqueia,
    alerta: alertas.join(' | '),
    // usado pelo node de pesquisa; sem documento nao ha como deduplicar
    podeDeduplicar: docStatus === 'cpf' || docStatus === 'cnpj',
  };
}
// --- saida do node -----------------------------------------------------------
const saida = [];
let ignoradasPorData = 0;

for (const entrada of $input.all()) {
  const r = entrada.json ?? {};
  // linha em branco (acontece quando alguem mexe na planilha): ignora
  if (!limpa(r['Carimbo de data/hora']) && !limpa(r['Nome completo'])) continue;

  const n = normalizarLinha(r);

  // TRAVA DE HISTORICO: resposta anterior ao corte nao entra no Tiny.
  // Carimbo ilegivel tambem nao passa — sem data nao da para saber se e antiga.
  const chave = chaveDoCarimbo(n.carimbo);
  if (chave === null || chave < PROCESSAR_A_PARTIR_DE) { ignoradasPorData++; continue; }

  saida.push({ json: n });
}

// Aparece no painel do node em "Logs" — util no primeiro teste.
console.log(`recebidas ${$input.all().length} | processadas ${saida.length} | ` +
            `ignoradas por serem anteriores a ${PROCESSAR_A_PARTIR_DE}: ${ignoradasPorData}`);

return saida;

// ============================================================================
// Node "Aplicar cidade do CEP". Mode: Run Once for EACH Item.
//
// POR QUE EXISTE (incidente de 03/09):
// O Tiny recusou um cadastro com codigo_erro 31 - "O nome municipio nao foi
// localizado na lista de cidade". Medindo as 77 respostas dos ultimos 12 meses,
// ~5% seriam recusadas, e TRES EM CADA QUATRO so por acento faltando
// ("Macaiba", "Cerro Cora", "Sao Jose de Mipibu"). O CEP e o campo que o
// cliente acerta mais, entao ele vira a fonte da verdade para cidade e UF.
//
// REGRA: a cidade do ViaCEP substitui a digitada. Quando a diferenca e so de
// acento ou caixa, a troca e silenciosa. Quando a cidade muda de verdade
// (ou a UF), vira alerta na PENDENCIAS para alguem conferir - pode ser CEP
// digitado errado.
// ============================================================================

function itemDoNode(nomeBase, idx) {
  for (const nome of [nomeBase, nomeBase + '1', nomeBase + '2']) {
    try {
      const it = $(nome).itemMatching(idx);
      if (it) return it.json;
    } catch (e) { /* node com esse nome nao existe: tenta o proximo */ }
  }
  throw new Error(
    `Nao encontrei o node "${nomeBase}". Se voce renomeou os nodes, ` +
    `importe o workflow num fluxo NOVO e vazio para os nomes voltarem ao original.`
  );
}

// compara ignorando acento e caixa: "Macaiba" e "Macaíba" sao a mesma coisa
const chave = (s) => String(s ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/\s+/g, ' ').trim();

const n = itemDoNode('Normalizar e validar', $itemIndex);
const v = $json ?? {};

const contato = { ...n.contato };
const alertas = n.alerta ? n.alerta.split(' | ') : [];

const localidade = typeof v.localidade === 'string' ? v.localidade.trim() : '';
const ufDoCep = typeof v.uf === 'string' ? v.uf.trim().toUpperCase() : '';
// o ViaCEP devolve {"erro": true} quando o CEP nao existe
const achou = !v.erro && localidade !== '' && /^[A-Z]{2}$/.test(ufDoCep);

let cidadeAjustada = false;

if (achou) {
  const cidadeAntes = contato.cidade ?? '';
  const ufAntes = contato.uf ?? '';
  const mesmaCidade = chave(cidadeAntes) === chave(localidade);
  const mesmaUF = ufAntes === '' || ufAntes === ufDoCep;

  contato.cidade = localidade.slice(0, 30);
  contato.uf = ufDoCep;
  cidadeAjustada = true;

  // bairro do ViaCEP so preenche quando o cliente deixou em branco
  if (!contato.bairro && typeof v.bairro === 'string' && v.bairro.trim()) {
    contato.bairro = v.bairro.trim().slice(0, 30);
  }

  // troca substantiva (nao e so acento/caixa) merece olho humano
  if (!(mesmaCidade && mesmaUF)) {
    alertas.push(
      `Cidade/UF trocadas pelo CEP ${contato.cep || n.cepDigitos}: ` +
      `"${cidadeAntes || '(vazio)'}/${ufAntes || '--'}" -> "${localidade}/${ufDoCep}" ` +
      `- conferir se o CEP esta certo`
    );
  }
} else if (n.cepDigitos) {
  alertas.push(`CEP ${contato.cep || n.cepDigitos} nao foi reconhecido pelo ViaCEP - ` +
               `cidade e UF ficaram como o cliente digitou`);
}
// sem CEP nenhum: o alerta "CEP nao reconhecido" ja veio de Normalizar e validar

// a UF em branco deixa de ser alerta quando o CEP resolveu
const alertasFinais = alertas.filter((a) => !(cidadeAjustada && a === 'UF em branco'));

return { json: { ...n, contato, cidadeAjustada, alerta: alertasFinais.join(' | ') } };

// ============================================================================
// Node "Decidir incluir ou alterar". Mode: Run Once for EACH Item.
// (precisa ser "each item" para o itemMatching casar a resposta da pesquisa
//  com a resposta do formulario que a originou)
//
// Le o retorno de contatos.pesquisa.php e decide:
//   - achou o MESMO documento -> contato.alterar (com o id do Tiny)
//   - nao achou               -> contato.incluir
//   - a pesquisa falhou       -> nao mexe no Tiny, vai para PENDENCIAS
//
// TRAVA IMPORTANTE: so tratamos como "ja existe" quando os digitos do
// cpf_cnpj devolvido sao EXATAMENTE os nossos. Se um dia o Tiny ignorar o
// filtro e devolver uma lista larga, a automacao inclui um contato novo em
// vez de sobrescrever o cadastro de outra pessoa.
// ============================================================================

// Busca o item correspondente no node de origem, tolerando o sufixo que o n8n
// acrescenta ao nome quando o workflow e importado por cima de outro ("...1").
// Sem isso, um import duplicado quebra a referencia em tempo de execucao.
function itemDoNode(nomeBase, idx) {
  for (const nome of [nomeBase, nomeBase + '1', nomeBase + '2']) {
    try {
      const it = $(nome).itemMatching(idx);
      if (it) return it.json;
    } catch (e) { /* node com esse nome nao existe: tenta o proximo */ }
  }
  throw new Error(
    `Nao encontrei o node "${nomeBase}". Se voce renomeou os nodes, ` +
    `importe o workflow num fluxo NOVO e vazio para os nomes voltarem ao original.`
  );
}

// le o item JA corrigido pelo ViaCEP - nao trocar por 'Normalizar e validar',
// senao a cidade oficial se perde e o Tiny volta a recusar com codigo 31.
const n = itemDoNode('Aplicar cidade do CEP', $itemIndex);
const ret = $json?.retorno ?? {};
const dig = (v) => String(v ?? '').replace(/\D/g, '');

let acao = 'incluir';
let idTiny = '';
let erroPesquisa = '';

// SEM DOCUMENTO: nao ha o que deduplicar, entao a resposta da pesquisa e
// IRRELEVANTE - inclusive quando ela vem como erro.
// Achado em 03/09: mandamos '00000000000' como sentinela e o Tiny responde
// "O CPF/CNPJ informado e invalido" em vez do codigo 20 ("sem registros").
// Sem esta saida antecipada, o cliente sem CPF valido nunca era cadastrado -
// o oposto da regra aprovada em 13/08 (cadastrar sem documento + avisar).
if (!n.podeDeduplicar) {
  acao = 'incluir';
} else if (ret.status === 'OK') {
  const bruta = Array.isArray(ret.contatos) ? ret.contatos : (ret.contatos ? [ret.contatos] : []);
  const achados = bruta.map((x) => x.contato || x);
  if (n.podeDeduplicar) {
    const igual = achados.find((c) => dig(c.cpf_cnpj) === n.docDigitos);
    if (igual && igual.id) { acao = 'alterar'; idTiny = String(igual.id); }
  }
  // sem documento nunca vira "alterar": casar por nome sobrescreveria o
  // cadastro de outro cliente homonimo. Inclui e avisa na PENDENCIAS.
} else {
  const codigo = Number(ret.codigo_erro ?? 0);
  // 20 = "a consulta nao retornou registros" -> e o caso normal de cliente novo
  if (codigo !== 20) {
    erroPesquisa = JSON.stringify(ret.erros ?? ret).slice(0, 300);
  }
}

// monta o payload no formato que a API v2 espera
const contato = { ...n.contato };
if (acao === 'alterar') { contato.id = idTiny; delete contato.sequencia; }
const payload = JSON.stringify({ contatos: [{ contato }] });

return {
  json: {
    ...n,
    acao,
    idTiny,
    erroPesquisa,
    payload,
    // quando a pesquisa falhou de verdade nao arriscamos escrever no Tiny
    seguirParaTiny: erroPesquisa === '',
  },
};

// ============================================================================
// Node "Conferir resposta do Tiny". Mode: Run Once for EACH Item.
//
// O Tiny mente duas vezes seguidas: pode devolver retorno.status = "OK" e,
// dentro de registros[], um registro com status "Erro". Por isso conferimos
// os dois niveis antes de dar a resposta por boa.
// ============================================================================

// Busca o item correspondente no node de origem, tolerando o sufixo que o n8n
// acrescenta ao nome quando o workflow e importado por cima de outro ("...1").
// Sem isso, um import duplicado quebra a referencia em tempo de execucao.
function itemDoNode(nomeBase, idx) {
  for (const nome of [nomeBase, nomeBase + '1', nomeBase + '2']) {
    try {
      const it = $(nome).itemMatching(idx);
      if (it) return it.json;
    } catch (e) { /* node com esse nome nao existe: tenta o proximo */ }
  }
  throw new Error(
    `Nao encontrei o node "${nomeBase}". Se voce renomeou os nodes, ` +
    `importe o workflow num fluxo NOVO e vazio para os nomes voltarem ao original.`
  );
}

const d = itemDoNode('Decidir incluir ou alterar', $itemIndex);

// MODO DE TESTE: com o node "Tiny · contato.incluir ou alterar" DESATIVADO, o
// item chega aqui sem 'retorno' (o n8n so repassa a entrada). Nesse caso nao ha
// nada para conferir nem para registrar - o teste era so a pesquisa.
if ($json?.retorno === undefined && $json?.acao !== undefined) {
  return { json: {
    carimbo: d.carimbo, nome: d.contato?.nome ?? '',
    acao: d.acao, idTiny: d.idTiny,
    resultado: 'MODO DE TESTE - node de escrita no Tiny desativado, nada foi gravado',
    tinyOk: null, erroDoTiny: false, pendencia: false,
  }};
}

const ret = $json?.retorno ?? {};

const regs = Array.isArray(ret.registros) ? ret.registros : (ret.registros ? [ret.registros] : []);
const reg = (regs[0] || {}).registro || regs[0] || {};

const juntaErros = (e) => {
  const lista = Array.isArray(e) ? e : (e ? [e] : []);
  return lista.map((x) => (typeof x === 'string' ? x : (x.erro ?? JSON.stringify(x)))).join(' / ');
};

const erroTopo = juntaErros(ret.erros);
const erroReg = juntaErros(reg.erros);
const okTopo = String(ret.status ?? '').toUpperCase() === 'OK';
const okReg = reg.status === undefined || String(reg.status).toUpperCase() === 'OK';
const ok = okTopo && okReg;

const motivoTiny = ok ? '' : (erroReg || erroTopo ||
  `Tiny recusou (codigo ${ret.codigo_erro ?? reg.codigo_erro ?? '?'})`).slice(0, 300);

// idTiny: no incluir vem no registro; no alterar ja tinhamos
const idTiny = String(reg.id ?? d.idTiny ?? '');

// A linha vai para PENDENCIAS se o Tiny recusou OU se a resposta do cliente
// tinha algum problema que um humano precisa olhar.
const motivo = [motivoTiny ? `Tiny: ${motivoTiny}` : '', d.alerta || '']
  .filter(Boolean).join(' | ');

return {
  json: {
    carimbo: d.carimbo,
    nome: d.contato?.nome ?? '',
    telefone: d.contato?.fone ?? '',
    email: d.contato?.email ?? '',
    documentoInformado: d.docBruto,
    documentoGravado: d.contato?.cpf_cnpj ?? '',
    tipoPessoa: d.tipo_pessoa,
    acao: d.acao,
    idTiny,
    tinyOk: ok,
    resultado: ok
      ? (d.acao === 'alterar' ? `Contato ATUALIZADO no Tiny (id ${idTiny})`
                              : `Contato CRIADO no Tiny (id ${idTiny})`)
      : 'NAO foi gravado no Tiny',
    motivo,
    erroDoTiny: !ok,
    pendencia: motivo !== '',
  },
};

// ============================================================================
// Node "Montar linha de pendencia". Mode: Run Once for All Items.
//
// Recebe itens de tres lugares com formatos diferentes:
//   a) "Da para cadastrar?" (falso)  -> resposta impossivel de cadastrar
//   b) "Pesquisa respondeu?" (falso) -> contatos.pesquisa falhou
//   c) "Precisa de pendencia?" (sim) -> passou pelo Tiny mas tem o que olhar
// Aqui os tres viram a MESMA linha da aba PENDENCIAS.
// ============================================================================

const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Fortaleza' });
const txt = (v) => (v === null || v === undefined ? '' : String(v));

// Blindagem contra o auto-parse do Google Sheets — mesma tecnica do workflow
// Tiny -> Planilha. Com cellFormat = USER_ENTERED, o apostrofo inicial forca
// texto literal e NAO e gravado na celula.
// Motivo (achado em 03/09): o CPF "08735920777" foi gravado como o NUMERO
// 8735920777 e perdeu o zero a esquerda — exatamente o bug de SKU do Plugga.
const texto = (v) => { const x = txt(v); return x === '' ? '' : "'" + x; };

const saida = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  const c = j.contato ?? {};

  const motivo = txt(j.motivo) || txt(j.erroPesquisa && `contatos.pesquisa falhou: ${j.erroPesquisa}`) ||
                 txt(j.alerta) || 'Sem motivo registrado';

  const resultado = txt(j.resultado) ||
    (j.erroPesquisa ? 'NAO foi gravado no Tiny (a pesquisa falhou)' : 'NAO foi gravado no Tiny');

  saida.push({ json: {
    'Registrado em': agora,
    'Carimbo da resposta': txt(j.carimbo),
    'Nome': txt(j.nome) || txt(c.nome),
    'Telefone': texto(txt(j.telefone) || txt(c.fone)),
    'E-mail': txt(j.email) || txt(c.email),
    'Documento informado': texto(txt(j.documentoInformado) || txt(j.docBruto)),
    'Documento gravado': texto(txt(j.documentoGravado) || txt(c.cpf_cnpj)),
    'Motivo': motivo.slice(0, 500),
    'O que a automação fez': resultado,
    'Erro do Tiny': j.erroDoTiny || j.erroPesquisa ? 'sim' : 'nao',
    'ID no Tiny': texto(txt(j.idTiny)),
    'Resolvido?': '',
  }});
}
return saida;
